 "content": "def transform(grid):
    """Connect consecutive marker cells that share a row or column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v != grid[0][0]), None)
    if marker is None:
        return out
    line = 3
    # Fill only cells between consecutive markers in each row.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = line
    # Fill only cells between consecutive markers in each column.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = line
    return out
